import json
G=[[5]*12 for _ in range(28)]
G[25][8]=2; G[26][6]=0; G[26][7]=2; G[27][6]=2; G[27][7]=0
# Extend the unobstructed outward diagonal ray for each diagonal-color chain.
for r,c in [(26,6)]:
    rr,cc=r-1,c-1
    while rr>=0 and cc>=0:
        G[rr][cc]=0; rr-=1; cc-=1
for r,c in [(25,8)]:
    rr,cc=r-1,c+1
    while rr>=0 and cc<12:
        G[rr][cc]=2; rr-=1; cc+=1
print(json.dumps({'action':'submit','grid':G},separators=(',',':')))
